long handle_deduplication_ioctl(struct file *file, void __user *arg)
{
    int dest_count;
    struct deduplication_params *params_user, *params_kernel;
    long ret = 0;

    if (copy_from_user(&dest_count, arg, sizeof(int)))
        return -EFAULT;

    params_kernel = kmalloc(sizeof(*params_kernel) + dest_count * sizeof(struct file_range), GFP_KERNEL);
    if (!params_kernel)
        return -ENOMEM;

    if (copy_from_user(params_kernel, arg, sizeof(*params_kernel)))
        ret = -EFAULT;
    else {
        params_user = arg;
        params_kernel->dest_count = dest_count;
        ret = perform_deduplication(file, params_kernel);
        if (!ret)
            ret = copy_to_user(params_user, params_kernel, sizeof(*params_kernel));
    }

    kfree(params_kernel);
    return ret;
}

#include <linux/uaccess.h>

long handle_deduplication_ioctl(struct file *file, void __user *arg) {
    int dest_count;
    struct deduplication_params *user_params;
    struct deduplication_params *kernel_params;
    long ret = 0;

    if (copy_from_user(&dest_count, arg, sizeof(int)))
        return -EFAULT;

    kernel_params = kmalloc(sizeof(*kernel_params), GFP_KERNEL);
    if (!kernel_params)
        return -ENOMEM;

    if (copy_from_user(kernel_params, arg, sizeof(*kernel_params))) {
        kfree(kernel_params);
        return -EFAULT;
    }

    ret = perform_deduplication(file, kernel_params);

    if (copy_to_user(arg, kernel_params, sizeof(*kernel_params))) {
        ret = -EFAULT;
    }

    kfree(kernel_params);
    return ret;
}
